-- V030: identity (docs/research-merge-import.md §3, milestone M0).
--
-- A citekey or a slug is a LABEL: human, mutable (`rename`), and two collections can use the same
-- one for different works. Merging two collections needs an IDENTITY that is none of that, so:
--
--   * `instance` — one row, generated by this migration: the id of THIS collection. A pg_dump/restore
--     carries it (a restored backup IS the same collection); a bundle import does not.
--   * `uid uuid` on every row a bundle carries — opaque, global (UUIDv7: time-ordered, no
--     coordination between instances), assigned at creation and never changed. `rename` changes the
--     citekey and keeps the uid.
--   * `origin uuid` — the instance that CREATED the row. Back-filled to this instance; a row brought
--     in by `bundle import` keeps the origin it had in the bundle.
--   * `updated_at` on the tables that had no change clock, so `bundle export --since` can tell what
--     changed. A BEFORE UPDATE trigger moves it unless the writer set it explicitly.
--   * the sets a row OWNS but that have no identity of their own (a source's edges, an event's
--     datings/edges/participants) move their owner's `updated_at` when they change, so an
--     incremental export carries the owner — and with it the whole set — again.
--
-- Every trigger here stands aside while `histmersion.importing` is 'on' (SET LOCAL by the bundle
-- importer): an import writes the bundle's own timestamps and tombstones, and must not invent new ones.
-- Back-fills use UPDATE rather than a volatile column default, so a table with large TOASTed values
-- (assets.bytes, sources.ocr_markdown) is not rewritten — the new column is all that is written.

CREATE TABLE IF NOT EXISTS instance (
  id         uuid        PRIMARY KEY DEFAULT uuidv7(),
  label      text,
  created_at timestamptz NOT NULL DEFAULT now(),
  singleton  boolean     NOT NULL DEFAULT true UNIQUE CHECK (singleton)   -- at most one row
);
INSERT INTO instance (id) SELECT uuidv7() WHERE NOT EXISTS (SELECT 1 FROM instance);

-- The default of every `origin` column. STABLE: one value per statement.
CREATE OR REPLACE FUNCTION histmersion_instance_id() RETURNS uuid
  LANGUAGE sql STABLE AS $$ SELECT id FROM instance LIMIT 1 $$;

-- 'on' while the bundle importer runs (SET LOCAL, so it ends with the transaction).
CREATE OR REPLACE FUNCTION histmersion_importing() RETURNS boolean
  LANGUAGE sql STABLE AS $$ SELECT coalesce(current_setting('histmersion.importing', true), '') = 'on' $$;

-- ── uid + origin ─────────────────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['sources', 'findings', 'articles', 'article_versions', 'assets',
                           'asset_links', 'attestations', 'events', 'goals', 'queue_items',
                           'places', 'periods']
  LOOP
    EXECUTE format('ALTER TABLE %I ADD COLUMN IF NOT EXISTS uid uuid', t);
    EXECUTE format('ALTER TABLE %I ADD COLUMN IF NOT EXISTS origin uuid', t);
    EXECUTE format('UPDATE %I SET uid = uuidv7() WHERE uid IS NULL', t);
    EXECUTE format('UPDATE %I SET origin = histmersion_instance_id() WHERE origin IS NULL', t);
    EXECUTE format('ALTER TABLE %I ALTER COLUMN uid SET DEFAULT uuidv7(), ALTER COLUMN uid SET NOT NULL', t);
    EXECUTE format('ALTER TABLE %I ALTER COLUMN origin SET DEFAULT histmersion_instance_id(), '
                   'ALTER COLUMN origin SET NOT NULL', t);
    EXECUTE format('ALTER TABLE %I ADD CONSTRAINT %I UNIQUE (uid)', t, t || '_uid_key');
  END LOOP;
END
$$;

-- ── a change clock where there was none ─────────────────────────────────────────────────────────
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['findings', 'assets', 'asset_links', 'attestations', 'events', 'queue_items']
  LOOP
    EXECUTE format('ALTER TABLE %I ADD COLUMN IF NOT EXISTS updated_at timestamptz', t);
  END LOOP;
END
$$;
-- the best "last changed" each table already knows; now() where it knows nothing
UPDATE findings     f SET updated_at = coalesce((SELECT s.updated_at FROM sources s WHERE s.citekey = f.citekey), now())
  WHERE updated_at IS NULL;
UPDATE assets       a SET updated_at = coalesce((SELECT s.updated_at FROM sources s WHERE s.citekey = a.citekey), now())
  WHERE updated_at IS NULL;
UPDATE attestations   SET updated_at = created_at WHERE updated_at IS NULL;
UPDATE queue_items    SET updated_at = greatest(created_at, coalesce(done_at, created_at)) WHERE updated_at IS NULL;
UPDATE asset_links    SET updated_at = now() WHERE updated_at IS NULL;
UPDATE events         SET updated_at = now() WHERE updated_at IS NULL;
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['findings', 'assets', 'asset_links', 'attestations', 'events', 'queue_items']
  LOOP
    EXECUTE format('ALTER TABLE %I ALTER COLUMN updated_at SET DEFAULT now(), '
                   'ALTER COLUMN updated_at SET NOT NULL', t);
  END LOOP;
END
$$;

-- An UPDATE moves `updated_at` unless the statement set it itself (an import restoring the bundle's
-- value does; every ordinary writer does not, and gets now()).
CREATE OR REPLACE FUNCTION histmersion_touch_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NOT histmersion_importing() AND NEW.updated_at IS NOT DISTINCT FROM OLD.updated_at THEN
    NEW.updated_at := now();
  END IF;
  RETURN NEW;
END
$$;

DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['findings', 'assets', 'asset_links', 'attestations', 'events', 'queue_items']
  LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS %I ON %I', t || '_touch_updated_at', t);
    EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE ON %I FOR EACH ROW '
                   'EXECUTE FUNCTION histmersion_touch_updated_at()', t || '_touch_updated_at', t);
  END LOOP;
END
$$;

-- ── owned sets move their owner ──────────────────────────────────────────────────────────────────
-- INSERT and DELETE only: the ON UPDATE CASCADE of a citekey rename (V027) rewrites `edges.src` while
-- the source row itself is being updated, and touching that row from inside the cascade is an error.
CREATE OR REPLACE FUNCTION histmersion_touch_source_of_edge() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  r record;
BEGIN
  IF histmersion_importing() THEN RETURN NULL; END IF;
  r := CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  UPDATE sources SET updated_at = now() WHERE citekey = r.src AND updated_at <> now();
  RETURN NULL;
END
$$;
DROP TRIGGER IF EXISTS edges_touch_source ON edges;
CREATE TRIGGER edges_touch_source AFTER INSERT OR DELETE ON edges
  FOR EACH ROW EXECUTE FUNCTION histmersion_touch_source_of_edge();
DROP TRIGGER IF EXISTS unresolved_edges_touch_source ON unresolved_edges;
CREATE TRIGGER unresolved_edges_touch_source AFTER INSERT OR DELETE ON unresolved_edges
  FOR EACH ROW EXECUTE FUNCTION histmersion_touch_source_of_edge();

-- An event's datings and participants (event_id) and its OUTGOING edges (src_id) are part of it.
-- `put_event` also deletes the edges coming IN, so an edge moves its source event either way.
CREATE OR REPLACE FUNCTION histmersion_touch_event() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  r record;
  ev text;
BEGIN
  IF histmersion_importing() THEN RETURN NULL; END IF;
  r := CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  -- two statements, not a CASE: a CASE names both fields, and a record has only one of them
  IF TG_TABLE_NAME = 'event_edges' THEN ev := r.src_id; ELSE ev := r.event_id; END IF;
  UPDATE events SET updated_at = now() WHERE id = ev AND updated_at <> now();
  RETURN NULL;
END
$$;
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['event_datings', 'event_edges', 'event_participants']
  LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS %I ON %I', t || '_touch_event', t);
    EXECUTE format('CREATE TRIGGER %I AFTER INSERT OR UPDATE OR DELETE ON %I FOR EACH ROW '
                   'EXECUTE FUNCTION histmersion_touch_event()', t || '_touch_event', t);
  END LOOP;
END
$$;
